export function AppRoot() {
  const routedPath = window.location.pathname;
  const routedPage = routedPath === '/visa-consultancy' ? <VisaServicesPage /> : routedPath === '/school-placement' ? <SchoolPage /> : routedPath === '/curated-tours' ? <ToursHolidayPage /> : routedPath === '/group-tours' ? <GroupToursPage /> : routedPath === '/corporate-travel' ? <CorporateTravelPage /> : routedPath === '/concierge-lifestyle' ? <ConciergeLifestylePage /> : routedPath === '/tickets-and-aviation' ? <FlightTicketingPage /> : null;
  return <SiteChrome>{routedPage || <App />}</SiteChrome>;
}

export default App;
